import re
def strip(h): return re.sub(r'<[^>]+>',' ',h or '')
w = sum(len(strip(b.get('html','')).split()) for g in lr['groups'] for b in g['blocks'] if b.get('t')=='p')
print('LR47 written, chapters:', len(lr['groups']), 'words:', w)
